"""50 individually checked LEP foundations, assistance, work, rights and discipline."""
exec(compile(open('scripts/review/reviewed-course-overlay.py').read(),'reviewed-course-overlay.py','exec'))
add(1,'Execução cumpre a decisão criminal e organiza condições de reintegração.','Isolamento sem assistência não realiza automaticamente a segunda finalidade.','A lei tem finalidade exclusivamente retributiva? Não.','Internado está incluído? Sim.')
add(2,'Preso provisório recebe assistência nos termos da LEP.','Condenado militar em unidade sujeita à jurisdição ordinária tem recorte expresso; não importar toda execução militar automaticamente.','A LEP só vale após condenação definitiva? Não.','Local/jurisdição importa na extensão a condenação militar? Sim.')
add(3,'Preso mantém direitos não atingidos pela sentença ou lei.','Prisão não autoriza discriminação racial,religiosa ou política.','Sentença retira todos os direitos? Não.','Distinção racial é autorizada pela classificação? Não.')
add(4,'Comunidade coopera em projeto de reintegração sob responsabilidade pública.','Cooperar não transfere competência judicial para voluntários.','Alcança medida de segurança? Sim.','Cooperação elimina dever estatal? Não.')
add(5,'Classificação orienta programa individualizado segundo dados pertinentes.','Não usar estereótipo racial ou social como prova de personalidade.','É finalidade de individualização? Sim.','Classificar autoriza discriminação proibida pelo3? Não.')
add(6,'Comissão Técnica prepara programa adequado inclusive ao preso provisório.','Não confundir classificação com decisão judicial sobre progressão.','Programa cabe à Comissão Técnica? Sim.','Comissão substitui juiz na progressão? Não.')
add(7,'Comissão para condenado à pena privativa tem Diretor e composição mínima legal.','Nos demais casos há atuação junto ao juízo com fiscais do Serviço Social.','Dois chefes de serviço são previstos? Sim.','Diretor pode substituir toda equipe sozinho? Não.')
add(8,'Exame inicial de classificação no fechado fornece elementos para individualizar execução.','Progressão tem regime próprio do112; não copiar automaticamente facultatividade do semiaberto para toda progressão.','O exame deste artigo é de classificação? Sim.','Ele resolve sozinho exigência atual de progressão? Não.')
add(9,'Comissão requisita informações pertinentes observando ética e peças do processo.','Diligências necessárias não autorizam investigação arbitrária sem limites.','Pode entrevistar pessoas? Sim.','Ética profissional é dispensável? Não.')
add(10,'Estado oferece assistência e apoio ao retorno social do egresso.','Libertação não exclui imediatamente toda assistência prevista para egresso.','É dever estatal? Sim.','Alcança egresso? Sim.')
add(11,'Plano inclui assistência material,saúde,jurídica,educacional,social e religiosa.','Só alimentação não substitui as outras cinco vertentes.','Há seis espécies no rol? Sim.','Religiosa é a única forma de reintegração prevista? Não.')
add(12,'Administração fornece alimentação,vestuário e instalações higiênicas.','Compra eventual na cantina não substitui assistência básica estatal.','Instalações higiênicas integram assistência material? Sim.','Só roupa integra o rol? Não.')
add(13,'Unidade mantém serviços pessoais e venda de produtos permitidos não fornecidos.','Comercialização de produto proibido não é autorizada pelo artigo.','Permissão do objeto importa? Sim.','Cantina elimina o dever de alimentação? Não.')
add(14,'Unidade sem estrutura providencia assistência médica em outro local com autorização da direção.','Gestação,pós-parto,puerpério e recém-nascido têm proteção específica,sem condicioná-la a favor disciplinar.','Saúde é apenas curativa? Não;preventiva também.','Só médico,sem atendimento farmacêutico/odontológico,esgota rol? Não.')
add(15,'Internado sem recursos recebe assistência jurídica.','Esse critério não equivale a negar defesa a quem tenha capacidade econômica; distinguir meios de defesa.','Hipossuficiência é recorte da assistência? Sim.','Assistência jurídica se limita a presos condenados? Não;internados também.')
add(16,'Defensoria atende dentro da unidade e núcleo externo auxilia egresso hipossuficiente.','Familiares sem recursos também entram no§3º; não reduzir serviço às celas.','Há local apropriado em todos os estabelecimentos? Sim.','Auxílio estrutural estatal é previsto? Sim.')
add(17,'Preso recebe instrução escolar e formação profissional.','Curso profissional sozinho não esgota a instrução escolar.','Internado também está incluído? Sim.','Educação é apenas alfabetização? Não.')
add(18,'Ensino fundamental é organizado no sistema escolar estadual aplicável.','Expressão histórica primeiro grau não cria nível escolar atual distinto.','Ensino mencionado é obrigatório? Sim.','Terminologia antiga substitui estrutura educacional vigente? Não.')
add('18-a','Presídio implanta ensino médio e oferta educação de jovens/adultos no regime legal.','Ensino a distância e tecnologias também devem incluir presos; não dispensar qualidade/integração escolar.','A União pode apoiar financiamento? Sim.','O artigo só prevê ensino fundamental? Não.')
add(19,'Formação profissional oferece iniciação ou aperfeiçoamento técnico.','Adequação à condição da mulher não autoriza restringir profissão por estereótipo.','Há duas modalidades expressas? Sim.','Adequar equivale a excluir mulheres de formação técnica? Não.')
add(20,'Entidade particular conveniada oferece curso especializado.','Convênio não elimina responsabilidade estatal pela assistência educacional.','Entidades públicas também podem conveniar? Sim.','Só particulares são admitidos? Não.')
add(21,'Biblioteca dispõe de livros instrutivos,recreativos e didáticos para todas as categorias.','Excluir uma categoria só por conveniência não realiza a abrangência prevista.','Livros recreativos estão incluídos? Sim.','Biblioteca se destina apenas a condenados definitivos? Não;texto diz todas as categorias de reclusos.')
add('21-a','Censo registra escolaridade,cursos,atendidos e condição do acervo.','Contar matrículas sem examinar bibliotecas não esgota o rol.','Cursos profissionais entram? Sim.','Rol impede outros dados relevantes? Não;incisoV.')
add(22,'Assistência social prepara internado para retorno à liberdade.','Só administrar disciplina não substitui amparo social.','Amparo e preparação são finalidades? Sim.','Internado fica fora? Não.')
add(23,'Serviço social orienta família da vítima quando necessário e acompanha resultados de saídas legais.','Acompanhamento não concede saída por si nem restaura modalidade revogada.','Família da vítima está prevista? Sim.','Assistente social substitui juiz na autorização de saída? Não.')
add(24,'Preso pode participar de culto ou recusar atividade religiosa.','Participação não pode ser condição coercitiva de benefício disciplinar.','Existe liberdade de culto? Sim.','Pode obrigar quem recusa? Não.')
add(25,'Egresso necessitado recebe alojamento e alimentação por dois meses.','Prorrogação única exige declaração do assistente social sobre empenho em obter emprego; não benefício indefinido.','A concessão material depende de necessidade? Sim.','Há prorrogações ilimitadas? Não.')
add(26,'Liberado definitivo permanece egresso por um ano desde a saída.','Liberado condicional tem condição durante período de prova,sem copiar prazo de um ano.','Os dois prazos são idênticos? Não.','Um ano começa na sentença? Não;na saída do estabelecimento.')
add(27,'Serviço social colabora para obtenção de trabalho pelo egresso.','Colaboração não equivale a garantia automática de cargo público ou contratação.','Há apoio à inserção laboral? Sim.','Lei exige empregador contratar toda pessoa indicada? Não.')
add(28,'Trabalho prisional tem finalidade educativa/produtiva e segurança/higiene.','Exclusão da CLT não autoriza trabalho sem proteção ou sem dignidade.','Métodos devem observar segurança? Sim.','Ausência de vínculo CLT retira toda proteção? Não.')
add(29,'Remuneração observa tabela,piso legal e destinações protegidas antes do pecúlio.','Ressarcimento estatal não pode consumir valores prejudicando destinações anteriores.','Dano precisa ser judicialmente determinado e não reparado? Sim.','Todo valor vai diretamente ao Estado? Não.')
add(30,'Prestação de serviços à comunidade não gera remuneração pelas tarefas.','Não transportar essa gratuidade para todo trabalho prisional do29.','As tarefas deste artigo são remuneradas? Não.','Todo trabalho do condenado é gratuito? Não.')
add(31,'Condenado trabalha conforme aptidão e capacidade.','Preso provisório não é obrigado e seu trabalho tem recorte interno.','Trabalho provisório é obrigatório? Não.','Obrigatoriedade dispensa capacidade/aptidão? Não.')
add(32,'Pessoa com limitação física recebe atividade apropriada ao seu estado.','Maior de sessenta pode solicitar adequação; não excluir automaticamente toda capacidade laboral.','O mercado e necessidades futuras importam? Sim.','Toda atividade manual é proibida? Não;artesanato tem recorte e ressalva turística.')
add(33,'Jornada normal é de seis a oito horas,com descanso em domingos/feriados.','Conservação/manutenção pode ter horário especial; não universalizar exceção para qualquer função.','Oito horas é mínimo? Não;máximo normal.','Horário especial tem hipótese expressa? Sim.')
add(35,'Produto prisional tem aquisição pública nas condições textuais quando venda particular não é possível/recomendável.','Não ensinar dispensa irrestrita de todo procedimento de contratação; integrar regime atual aplicável.','Receita tem destinação vinculada? Sim.','Qualquer aquisição pública é dispensada por este artigo? Não.')
add(36,'Preso do fechado presta trabalho externo em obra pública com cautelas pertinentes.','Obra privada comum não se torna pública só porque emprega preso; serviço a entidade privada exige consentimento expresso.','Teto é10% dos empregados da obra? Sim.','Consentimento expresso é previsto para entidade privada? Sim.')
add(37,'Direção examina aptidão,disciplina e responsabilidade para trabalho externo.','O lapso textual de1/6 exige distinguir regime e jurisprudência; não fórmula universal para todo semiaberto/progressão.','Autorização é administrativa neste recorte? Sim.','Artigo dá autorização automática ao completar fração? Não.')
add(38,'Condenado cumpre normas legais de execução.','Obediência não legitima ordem ilícita nem sanção sem base anterior.','Há deveres de execução além de outras obrigações legais? Sim.','Pode inventar obrigação incompatível com lei? Não.')
add(39,'Dever de indenizar Estado tem condição quando possível e desconto proporcional.','Ao provisório aplica-se no que couber; não tornar trabalho obrigatório por essa extensão.','Condicionalidade econômica importa? Sim.','No que couber torna idênticos todos os deveres? Não.')
add(40,'Autoridades preservam integridade física e moral do provisório.','Sanção disciplinar não autoriza tortura ou degradação.','Proteção inclui provisório? Sim.','Disciplina dispensa integridade moral? Não.')
add(41,'Restrição dos incisosV,X,XV requer ato motivado do juiz no texto atual.','Direção não deve copiar competência antiga; visita íntima/conjugal tem restrição específica do§2º,sem vedar toda visita familiar.','Atestado de pena é anual? Sim.','§2º proíbe automaticamente qualquer visita de familiar? Não.')
add('41-a','Encontro de visitante com preso vinculado aos grupos expressos tem previsão específica de monitoramento.','Mera prisão não demonstra vínculo; comunicação com defensor exige41-B e proteção do sigilo.','Requerimento equivale a autorização geral sem limites? Não.','Presídio federal tem regras especiais? Sim.')
add('41-b','Conluio criminoso fundadamente reconhecido judicialmente exige controle por juízo distinto antes de remessa.','Juízo de instrução não acessa direta/indiretamente comunicação ilícita ou indeferida.','Pode monitorar todo advogado pela profissão? Não.','Inutilização exige decisão fundamentada no recorte? Sim.')
add(42,'Direitos/deveres da seção alcançam provisório e medida de segurança no que couber.','Compatibilidade exige exame,não cópia automática de toda regra do condenado.','Há ressalva de compatibilidade? Sim.','Todo direito é eliminado pela provisoriedade? Não.')
add(43,'Família contrata médico de confiança para acompanhar internado.','Divergência com médico oficial é resolvida pelo juiz,não pelo particular sozinho.','Tratamento ambulatorial também está previsto? Sim.','Médico particular substitui automaticamente decisão judicial? Não.')
add(44,'Condenado à restritiva também está sujeito à disciplina compatível.','Não importar disciplina carcerária inteira sem considerar pena/regime e direitos.','Preso provisório está incluído? Sim.','Só condenado à privativa tem disciplina? Não.')
add(45,'Sanção precisa de previsão anterior e não pode ameaçar integridade.','Ainda que haja infração,sanção coletiva e cela escura são vedadas.','Pode criar punição depois do fato? Não.','Disciplina autoriza sanção coletiva? Não.')
add(46,'Normas disciplinares são comunicadas no início da prisão/execução.','Informação não permite criar norma retroativa ou sanção ilegal.','Denunciado também está no texto? Sim.','Só se comunica após primeira falta? Não.')
add(47,'Autoridade administrativa exerce disciplina da pena privativa conforme regulamento.','Não confundir com a competência judicial específica de restrição do41 ou RDD.','Todo ato disciplinar pertence exclusivamente ao juiz? Não.','Poder administrativo autoriza afastar regras judiciais específicas? Não.')
note(8,'Exame inicial de classificação não se confunde com exame para progressão,alterado por Lei14.843/2024 e sujeito à jurisprudência/irretroatividade aplicáveis. Não certificada aqui toda decisão posterior sobre112; sem exercício literal universal de progressão.')
patch(8,termos=[dict(termo='Exame criminológico de classificação',significado='Avaliação técnica prevista neste artigo para individualização; não decisão automática de periculosidade,culpa ou progressão.')])
note(14,'§4º incluído pela Lei14.326/2022: distinguir alteração normativa,data original da LEP e data de conferência.')
for n in ['18-a','21-a']:note(n,'Incluído pela Lei13.163/2015,não dispositivo original de1984. O número isolado7.627 encontrado no compilado junto ao18-A não foi tratado como requisito normativo.')
note(19,'Adequação não autoriza discriminação de gênero ou restringir formação por estereótipo.')
note(23,'Saídas dependem do regime atual de cada modalidade; acompanhamento social não revive hipótese revogada nem concede benefício por si.')
note(29,'Piso textual de3/4 não permite ressarcimento estatal prejudicando destinações anteriores do§1º; cálculo de remuneração e aplicações legais exigem caso concreto.')
note(29,'ADPF336: notícia oficial STF de8/3/2021 registra improcedência e recepção do piso de3/4 do salário mínimo. É mínimo,não teto; não autoriza remuneração zero em trabalho prisional remunerável.','https://noticias.stf.jus.br/postsnoticias/mantida-regra-que-permite-remuneracao-de-presos-em-3-4-do-salario-minimo/')
patch(29,pontos=['Remuneração por tabela,não inferior a3/4 do salário mínimo no texto.','Indenização judicialmente determinada e ainda não reparada,família,despesas pessoais.','Ressarcimento estatal proporcional sem prejudicar destinações anteriores.','Saldo para pecúlio,ressalvadas outras aplicações legais.'])
patch(35,pontos=['Aquisição pública de produto prisional nas condições textuais de impossibilidade/inconveniência da venda particular.','Remissão a dispensa de concorrência exige confronto com regime atual de contratação,não dispensa irrestrita.','Receitas para fundação/empresa pública gerenciadora;na falta,estabelecimento.'])
note(37,'Não universalizar1/6 para trabalho externo em todo regime,nem substituir requisitos de progressão. Condições e jurisprudência do regime precisam de exame específico.')
patch(37,simples='No recorte textual do37,o trabalho externo depende de autorização da direção,aptidão,disciplina,responsabilidade e lapso de1/6. Regime e jurisprudência aplicáveis precisam ser distinguidos; não converter a fração em fórmula universal do semiaberto ou progressão. Há hipóteses próprias de revogação.',pontos=['Autoridade administrativa e requisitos do recorte legal.','Lapso textual de1/6 exige integração ao regime/jurisprudência; não aplicação universal automática.','Crime,falta grave ou comportamento contrário aos requisitos têm disciplina própria de revogação.'],atencao=['Distinguir fechado,semiaberto e progressão. Não certificado neste lote todo precedente de dispensa/cômputo do lapso; sem exercício literal universal.'])
patch(39,simples='Deveres abrangem disciplina,respeito,trabalho compatível,indenização,higiene e conservação. Ressarcimento estatal: quando possível e com desconto proporcional da remuneração. Ao preso provisório aplicam-se no que couber,sem tornar obrigatório trabalho facultativo do31.')
note(41,'Lei14.994 publicada/vigente em10/10/2024 atribuiu restrição dos incisosV,X,XV ao juiz e inseriu§2º; distinguir visita íntima/conjugal de toda visita. Não certificada toda controvérsia constitucional posterior.')
for n in ['41-a','41-b']:note(n,'Lei15.358 publicada/vigente em25/3/2026. Controle constitucional da Antifacção não tratado como resolvido; previsão textual não autoriza monitoramento universal ou acesso automático ao sigilo profissional.')
patch('41-a',pontos=['Vínculo com grupos expressamente indicados precisa de prova,não apenas número de pessoas ou prisão.','Captação audiovisual/gravação de encontro do parlatório/virtual no recorte legal.','Requerentes e regras especiais federais expressos; integrar41-B em comunicação de defesa.'])
